---FillVo
---@param row TableML.TableFileRow
function MaidCoffeeHomeDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            self[key] = value
            if key == "cafeAvatars" then
                self:UpdateIdList(value)
            end

            if key == "avatarMall" then
                self:ConvertPrices(value)
            end
        end
    end

    if rawget(jsonData,"staffsEnergy") then
        self:UpdateCardEnergy(jsonData,jsonData.staffsEnergy)
    end

    if rawget(jsonData,"goldActivity") then
        if checkNumber(self.goldActivity.remainTime) > 0 then
            self.goldActivity.remainTime = checkNumber(self.goldActivity.remainTime) + os.time()
        end
    end

    if rawget(jsonData,"menus") then
        self:UpdateMenuDojoInfo(jsonData.menus)
    end

    if rawget(jsonData,"darkMerchant") then
        self:UpdateDarkMerchantTime()
    end

    ---刷新下外卖订单数据
    if jsonData.takeOutOrders and table.count(jsonData.takeOutOrders) > 0 then
        ---@type MaidCoffeePlayerComponent
        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        maidCoffeePlayerComponent:ResetTakeoutOrders(jsonData.takeOutOrders)
    end
end

function MaidCoffeeHomeDojo:UpdateDarkMerchantInfo(data)
    self.darkMerchant = data
    self:UpdateDarkMerchantTime()
end

function MaidCoffeeHomeDojo:ConvertPrices(data)
    if not data then return end
    if not data.products then return end
    for k, v in pairs(checkTable(data.products)) do
        if not isNull(v.prices) and next(v.prices) then
            for i, j in pairs(v.prices) do
                local tmp = {}
                tmp.current = j.current
                tmp.original = j.original
                tmp.currency = tonumber(i)
                v.prices = tmp
            end
        end
    end
end

function MaidCoffeeHomeDojo:IsInMallRenovateShop(furnitureId)
    if not isNull(self.avatarMall) and not isNull(self.avatarMall.products) then
        for i, v in pairs(self.avatarMall.products) do
            if v.avatarSuitId == furnitureId then
                return true
            end
        end
    end
    return false
end

function MaidCoffeeHomeDojo:GetMallRenovateShopData(furnitureId)
    if not isNull(self.avatarMall) and not isNull(self.avatarMall.products) then
        for i, v in pairs(self.avatarMall.products) do
            if v.avatarSuitId == furnitureId then
                return v
            end
        end
    end
    return nil
end

function MaidCoffeeHomeDojo:UpdateMenuDojoInfo(menus)
    for i, v in pairs(menus) do
        local menuDojo = self.menusDojo[i]
        if isNull(menuDojo) then
            menuDojo = MenuSellDojo.New()
        end
        if not isNull(menuDojo) then
            menuDojo:Fill(v)
            self.menusDojo[tonumber(i)] = menuDojo
        end
    end
end

function MaidCoffeeHomeDojo:UpdateCardEnergy(jsonData,value)
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    for i, v in pairs(value) do
        if checkNumber(i) ~= 0  then
            local id = checkNumber(jsonData.staffs[tostring(i)])
            if not isNull(id) and id ~= 0 then
                local cardDojo   = cardComp:GetCardById(id)
                if not isNull(cardDojo) then
                    local cafeEnergy = checkInt(v)
                    --- 更新下卡牌现在的心情
                    cardDojo:UpdateCardEnergy(cafeEnergy)
                end
            end
        end
    end
end

function MaidCoffeeHomeDojo:UpdateIdList(value)
    for i, v in pairs(value) do
        local vo = MaidCoffeeUtils.GetRenovateInfoVo(v)
        if vo then
            self.idToVo[tostring(v)] = vo
        end
    end
end

function MaidCoffeeHomeDojo:UpdateCafeAvatars(goodsId,data)
    table.insert(self.cafeAvatars,tostring(goodsId))
    self:UpdateIdList({goodsId})
end

