function MaidCoffeeHomeDojo:IsHaveMenuSell()
    if self.menusDojo then
        for i, v in pairs(self.menusDojo) do
            if v.remainTime > 0 then
                local time = v.remainTime - os.time()
                if time > 0 then
                    return true
                end
            end
        end
