function MaidCoffeeHomeDojo:GetRemainTimeMax()
    local time = 0
    if self.menusDojo then
        for i, v in pairs(self.menusDojo) do
            if v.remainTime > time then
                time = v.remainTime
            end
        end
    end
    if time > 0 then
        time = time - os.time()
    end
    return time
end

