function MaidCoffeeHomeDojo:IsQuestCompleteAll(vos)
    local isCompleteAll = false
    local count = 0
    for i, v in pairs(vos) do
        local number = v.taskContenNum
        local isComplete = self:JudgeIsCompleteQuest(v.refId,number)
        if isComplete then
            count = count + 1
        end
    end
    if count == #vos then
        isCompleteAll = true
    end
    return isCompleteAll
end

function MaidCoffeeHomeDojo:GetTaskProgress(index)
    local progress = 0
    if self.levelTaskProgress[tostring(index)] then
        progress = self.levelTaskProgress[tostring(index)]
    end
    return progress
end

function MaidCoffeeHomeDojo:JudgeIsCompleteQuest(index,num)
    local isComplete = false
    if self.levelTaskProgress[tostring(index)] and self.levelTaskProgress[tostring(index)] >= num then
        isComplete = true
    end
    return isComplete
end

